<script lang="ts">import {createSelectController} from "@weiui/core";import {normalizeSvelteProps} from "./internal.js";type Item={value:string;label?:string;disabled?:boolean};let {items=[],value=$bindable(""),placeholder="Select…",id="wui-select"}=$props<{items?:Item[];value?:string;placeholder?:string;id?:string}>();const controller=createSelectController({id,defaultValue:value,onValueChange:next=>value=next});controller.setItems(items);let state=$state(controller.getState());$effect(()=>{const off=controller.subscribe(next=>state=next);return off});$effect(()=>{controller.setItems(items);if(value!==state.value)controller.store.setState({...controller.getState(),value})});function p(kind:"root"|"trigger"|"content"|"item",index=0){state;return normalizeSvelteProps(kind==="root"?controller.getRootProps():kind==="trigger"?controller.getTriggerProps():kind==="content"?controller.getContentProps():controller.getItemProps(index))}let selected=$derived(items.find(item=>item.value===state.value));</script><div {...p("root")} class="wui-select"><button {...p("trigger")} class="wui-select__trigger">{selected?.label??placeholder}</button><div {...p("content")} class="wui-select__content">{#each items as item,index (item.value)}<div {...p("item",index)} class="wui-select__item">{item.label??item.value}</div>{/each}</div></div>
